  }

  .clear-completed:hover { color: var(--danger); }
  .clear-completed[hidden] { display: none; }
</style>
</head>
<body>
  <main class="app">
    <header>
      <h1>Todos</h1>
      <p>Stay on top of your day.</p>
    </header>

    <form class="composer" id="composer">
      <input type="text" id="todo-input" placeholder="What needs to be done?"
             autocomplete="off" maxlength="500" aria-label="New todo">
      <button type="submit">Add</button>
    </form>

    <div class="filters" role="group" aria-label="Filter todos">
      <button type="button" data-filter="all" class="active">All</button>
      <button type="button" data-filter="active">Active</button>
      <button type="button" data-filter="completed">Completed</button>
    </div>

    <ul class="todo-list" id="todo-list" aria-live="polite"></ul>
    <div class="empty-state" id="empty-state" hidden></div>

    <div class="stats">
      <span id="counter">0 items left</span>
      <button type="button" class="clear-completed" id="clear-completed" hidden>Clear completed</button>
    </div>
  </main>

<script>
(function () {
  'use strict';

  const STORAGE_KEY = 'todos.ollama-qwen3.8-flash-next-125b-a6b-q4_01';

  /** @type {{id:string,text:string,completed:boolean}[]} */
  let todos = load();
  let filter = 'all';

  const input = document.getElementById('todo-input');
  const form = document.getElementById('composer');
  const list = document.getElementById('todo-list');
  const emptyState = document.getElementById('empty-state');
  const counter = document.getElementById('counter');
  const clearBtn = document.getElementById('clear-completed');
  const filterButtons = Array.from(document.querySelectorAll('.filters button'));

  function load() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      const parsed = raw ? JSON.parse(raw) : [];
      return Array.isArray(parsed)
        ? parsed.filter(t => t && typeof t.text === 'string')
                .map(t => ({ id: String(t.id || uid()), text: t.text, completed: !!t.completed }))
        : [];
    } catch (e) {
      return [];
    }
  }

  function save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    } catch (e) { /* storage unavailable — app still works in-memory */ }
  }

  function uid() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  }

  function addTodo(text) {
    todos.unshift({ id: uid(), text: text, completed: false });
    save();
    render();
  }

  function toggleTodo(id) {
    const todo = todos.find(t => t.id === id);
    if (todo) {
      todo.completed = !todo.completed;
      save();
      render();
    }
  }

  function deleteTodo(id) {
    todos = todos.filter(t => t.id !== id);
    save();
    render();
  }

  function clearCompleted() {
    todos = todos.filter(t => !t.completed);
    save();
    render();
  }

  function visibleTodos() {
    if (filter === 'active') return todos.filter(t => !t.completed);
    if (filter === 'completed') return todos.filter(t => t.completed);
    return todos;
  }

  const EMPTY_MESSAGES = {
    all: 'Nothing here yet. Add your first todo!',
    active: 'No active todos — nice work!',
    completed: 'No completed todos yet.'
  };

  function render() {
    list.textContent = '';
    const items = visibleTodos();

    for (const todo of items) {
      const li = document.createElement('li');
      li.className = 'todo-item' + (todo.completed ? ' completed' : '');

      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.className = 'todo-checkbox';
      checkbox.checked = todo.completed;
      checkbox.setAttribute('aria-label',
        (todo.completed ? 'Mark as active: ' : 'Mark as complete: ') + todo.text);
      checkbox.addEventListener('change', () => toggleTodo(todo.id));

      const span = document.createElement('span');
      span.className = 'todo-text';
      span.textContent = todo.text;
      span.addEventListener('click', () => toggleTodo(todo.id));

      const del = document.createElement('button');
      del.type = 'button';
      del.className = 'delete-btn';
      del.textContent = '\u00d7';
      del.setAttribute('aria-label', 'Delete: ' + todo.text);
      del.addEventListener('click', () => deleteTodo(todo.id));

      li.append(checkbox, span, del);
      list.appendChild(li);
    }

    emptyState.hidden = items.length !== 0;
    if (items.length === 0) emptyState.textContent = EMPTY_MESSAGES[filter];

    const left = todos.filter(t => !t.completed).length;
    counter.textContent = left + (left === 1 ? ' item left' : ' items left');
    clearBtn.hidden = !todos.some(t => t.completed);
  }

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    const text = input.value.trim();
    if (!text) return;
    addTodo(text);
    input.value = '';
    input.focus();
  });

  filterButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      filter = btn.dataset.filter;
      filterButtons.forEach(b => b.classList.toggle('active', b === btn));
      render();
    });
  });

  clearBtn.addEventListener('click', clearCompleted);

  render();
})();
</script>
</body>
</html>
